12	// mustPlan / mustComplete 是测试里的便捷封装。
13	func mustPlan(t *testing.T, s *store, assetID, content, firstDue string, interval int) {
14		t.Helper()
15		if _, err := s.createPlan(assetID, content, firstDue, interval); err != nil {
16			t.Fatalf("createPlan(%s): %v", assetID, err)
17		}
18	}
19	
20	func mustComplete(t *testing.T, s *store, assetID, periodDue, doneDate, result string) (string, string) {
21		t.Helper()
22		_, due, next, err := s.completeMaintenance(assetID, periodDue, doneDate, result)
23		if err != nil {
24			t.Fatalf("completeMaintenance(%s %s): %v", assetID, periodDue, err)
25		}
26		return due, next
27	}
