29	// 基本建立与推进：首次到期、下一到期日按日历日推算，严格晚于完成日。
30	func TestPlanCreateAndComplete(t *testing.T) {
31		s := newTestStore(t)
32		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
33			t.Fatal(err)
34		}
35	
36		// 未知资产拒绝。
37		if _, err := s.createPlan("NOPE", "更换滤芯", "2026-11-01", 30); !errors.Is(err, errNotFound) {
38			t.Fatalf("未知资产应失败，得到 %v", err)
39		}
40		// 间隔非正、日期非法拒绝。
41		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-11-01", 0); err == nil {
42			t.Fatal("间隔 0 应拒绝")
43		}
44		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-02-30", 30); err == nil {
45			t.Fatal("非法日期应拒绝")
46		}
47		if len(s.data.Plans) != 0 || len(s.data.Events) != 0 {
48			t.Fatal("失败的建立不应留下计划或履历")
49		}
50	
51		mustPlan(t, s, "EQ-1", "更换滤芯", "2026-11-01", 30)
52		if got := len(s.data.Plans); got != 1 {
53			t.Fatalf("计划数 = %d, 想得到 1", got)
54		}
55		// 计划不可覆盖。
56		if _, err := s.createPlan("EQ-1", "别的保养", "2026-12-01", 10); !errors.Is(err, errConflict) {
57			t.Fatalf("已有计划应冲突，得到 %v", err)
58		}
59		// 建立履历恰一条。
60		ev := s.eventsOf("EQ-1")
61		if len(ev) != 1 || ev[0].Kind != eventPlanCreate || ev[0].Due != "2026-11-01" ||
62			ev[0].Content != "更换滤芯" || ev[0].TicketID != "" || ev[0].Done != "" {
63			t.Fatalf("建立履历不正确: %+v", ev)
64		}
65	
66		p := s.findPlan("EQ-1")
67		if next, err := s.planNextDue(p); err != nil || next != "2026-11-01" {
68			t.Fatalf("初始下一到期日 = %q, %v", next, err)
69		}
70	
71		// 无计划资产完成登记拒绝。
72		if _, err := s.registerAsset("EQ-2", "空调", "二楼"); err != nil {
73			t.Fatal(err)
74		}
75		if _, _, _, err := s.completeMaintenance("EQ-2", "2026-11-01", "2026-11-01", "结果"); !errors.Is(err, errConflict) {
76			t.Fatalf("无计划完成应冲突，得到 %v", err)
77		}
78		if _, _, _, err := s.completeMaintenance("NOPE", "2026-11-01", "2026-11-01", "结果"); !errors.Is(err, errNotFound) {
79			t.Fatalf("未知资产完成应未找到，得到 %v", err)
80		}
81	
82		// 到期日不匹配（提前完成下一周期 / 填错日期）拒绝。
83		if _, _, _, err := s.completeMaintenance("EQ-1", "2026-12-01", "2026-12-01", "结果"); !errors.Is(err, errConflict) {
84			t.Fatalf("非当前到期日应冲突，得到 %v", err)
85		}
86		// 完成日早于到期日拒绝。
87		if _, _, _, err := s.completeMaintenance("EQ-1", "2026-11-01", "2026-10-31", "结果"); !errors.Is(err, errConflict) {
88			t.Fatalf("完成日早于到期日应冲突，得到 %v", err)
89		}
90		if len(s.data.Events) != 1 {
91			t.Fatal("失败的完成登记不应产生履历")
92		}
93	
94		// 按期完成：下一到期日严格晚于完成日。11-01 完成，下一周期 12-01。
95		due, next := mustComplete(t, s, "EQ-1", "2026-11-01", "2026-11-01", "已更换")
96		if due != "2026-11-01" || next != "2026-12-01" {
97			t.Fatalf("完成输出 = %s -> %s，想得到 2026-11-01 -> 2026-12-01", due, next)
98		}
99		done := s.planDoneEvents("EQ-1")
100		if len(done) != 1 || done[0].Due != "2026-11-01" || done[0].Done != "2026-11-01" ||
101			done[0].Content != "已更换" || done[0].TicketID != "" {
102			t.Fatalf("完成履历不正确: %+v", done)
103		}
104		// 旧周期重复登记拒绝。
105		if _, _, _, err := s.completeMaintenance("EQ-1", "2026-11-01", "2026-11-02", "再来一次"); !errors.Is(err, errConflict) {
106			t.Fatalf("旧周期重复应冲突，得到 %v", err)
107		}
108		if len(s.data.Events) != 2 {
109			t.Fatal("旧周期重复不应产生履历")
110		}
111	}
