113	// 延期：跨过的周期不生成完成记录，下一到期日锚定首次到期日的整数倍间隔，
114	// 而不是完成日加间隔。
115	func TestPlanDeferredCompletionSkipsPeriods(t *testing.T) {
116		s := newTestStore(t)
117		_, _ = s.registerAsset("EQ-1", "水泵", "机房")
118		mustPlan(t, s, "EQ-1", "润滑", "2026-01-10", 30)
119	
120		// 周期：01-10, 02-09, 03-11, 04-10 ... 完成日 03-20（晚于 03-11，早于 04-10）。
121		// 必须用当前下一到期日 01-10 登记（跨两个周期只产生一条完成记录）。
122		if _, _, _, err := s.completeMaintenance("EQ-1", "2026-02-09", "2026-03-20", "延期完成"); !errors.Is(err, errConflict) {
123			t.Fatalf("非当前到期日（02-09）应拒绝，得到 %v", err)
124		}
125		_, next := mustComplete(t, s, "EQ-1", "2026-01-10", "2026-03-20", "延期完成")
126		if next != "2026-04-10" {
127			t.Fatalf("延期后下一到期日 = %s，想得到 2026-04-10（锚定首次到期日，非完成日+间隔）", next)
128		}
129		if got := len(s.planDoneEvents("EQ-1")); got != 1 {
130			t.Fatalf("跨过的周期不应生成完成记录，完成履历数 = %d", got)
131		}
132		// 下一周期按新到期日继续；04-10 + 30 天 = 05-10。
133		_, next = mustComplete(t, s, "EQ-1", "2026-04-10", "2026-04-10", "按期")
134		if next != "2026-05-10" {
135			t.Fatalf("再下一周期 = %s，想得到 2026-05-10", next)
136		}
137	}
