139	// 闰日与不同月份长度：按日历日推进；落在闰日的周期在平年归一到 2-28 或 3-1。
140	func TestPlanLeapDayCalendarArithmetic(t *testing.T) {
141		s := newTestStore(t)
142		_, _ = s.registerAsset("A", "设备A", "一楼")
143		_, _ = s.registerAsset("B", "设备B", "一楼")
144		// 首次到期 2024-02-29（闰日），间隔 365 天：
145		// 2025-02-28（365 天后），2026-02-28。
146		mustPlan(t, s, "A", "年检", "2024-02-29", 365)
147		_, next := mustComplete(t, s, "A", "2024-02-29", "2024-02-29", "完成")
148		if next != "2025-02-28" {
149			t.Fatalf("闰日 +365 = %s，想得到 2025-02-28", next)
150		}
151		_, next = mustComplete(t, s, "A", "2025-02-28", "2025-03-01", "完成")
152		if next != "2026-02-28" {
153			t.Fatalf("2025-02-28 +365 = %s，想得到 2026-02-28", next)
154		}
155	
156		// 按月末附近、间隔一个月（28~31 天）检查按日历日而非固定 30 天。
157		mustPlan(t, s, "B", "保养", "2024-01-31", 29)
158		p := s.findPlan("B")
159		if got, _ := s.planNextDue(p); got != "2024-01-31" {
160			t.Fatalf("初始 = %s", got)
161		}
162		_, next = mustComplete(t, s, "B", "2024-01-31", "2024-01-31", "x")
163		if next != "2024-02-29" {
164			t.Fatalf("01-31 +29 = %s，想得到 2024-02-29（闰日）", next)
165		}
166	}
