182		want := []dueRow{
183			{AssetID: "EQ-2", Name: "空调", Content: "清洗", Due: "2026-10-01"},
184			{AssetID: "EQ-1", Name: "打印机", Content: "更换滤芯", Due: "2026-11-01"},
185			{AssetID: "EQ-3", Name: "泵", Content: "润滑", Due: "2026-11-01"},
